        document.addEventListener('DOMContentLoaded', () => {
            const urlParams = new URLSearchParams(window.location.search);
            const service = urlParams.get('service');
            const product = urlParams.get('product');
            const tipoSolicitud = document.getElementById('tipo-solicitud');
            const queNecesita = document.getElementById('que-necesita');

            if (service) {
                tipoSolicitud.value = 'cotizacion-servicio';
                if (service === 'logo') queNecesita.value = 'Diseño de logo';
                else if (service === 'invitacion') queNecesita.value = 'Diseño de invitación digital';
                else if (service === 'flyer') queNecesita.value = 'Diseño de flyer/publicidad';
                else if (service === 'playera-diseno') queNecesita.value = 'Diseño para playera';
                else if (service === 'diseno-producto') queNecesita.value = 'Diseño para personalización de producto';
            } else if (product) {
                tipoSolicitud.value = 'cotizacion-producto';
                if (product === 'cilindro-chupón') queNecesita.value = 'Cilindro chupón personalizado';
                else if (product === 'cilindro-popote') queNecesita.value = 'Cilindro popote personalizado';
                else if (product === 'playera-sublimada') queNecesita.value = 'Playera blanca sublimada';
                else if (product === 'playera-dtf') queNecesita.value = 'Playera negra DTF';
                else if (product === 'taza-clasica') queNecesita.value = 'Taza clásica personalizada';
            }
        });
